// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Mantık: önermeler, çıkarımlar, safsatalar (zor).
const ozSocialscience13Zor = <(String, String, List<String>, String)>[
  ('İki önerme değişkeninden (p ve q) kurulabilecek birbirinden farklı doğruluk fonksiyonlarının sayısı kaçtır?', '16 fonksiyon', ['4 fonksiyon', '8 fonksiyon', '32 fonksiyon'], 'İki değişkenin tablosunda 4 satır vardır ve her satır doğru ya da yanlış olabileceğinden 2^4 = 16 farklı fonksiyon vardır.'),
  ('p: \'Hava açıktır\', q: \'Piknik yapılır\'. \'Hava açık olmadıkça piknik yapılmaz\' cümlesi hangi biçimle ifade edilir?', 'q → p', ['p → q', '¬p → q', 'p ↔ ¬q'], '\'Hava açık olmadıkça piknik yapılmaz\' demek piknik yapılıyorsa havanın açık olduğunu söyler: q → p.'),
  ('Yalnızca NAND (Sheffer çubuğu) bağlacı kullanılarak \'p\' önermesinin olumsuzu (¬p) nasıl elde edilir?', 'p ↑ p', ['p ↑ ¬p', '(p ↑ p) ↑ p', '(p ↑ p) ↑'], 'p ve p birlikte doğru değilse p yanlıştır: p ↑ p, ¬p ile aynı tabloyu verir.'),
  ('Peirce yasası olarak bilinen \'((p → q) → p) → p\' önermesi için hangisi doğrudur?', 'Totolojidir', ['Çelişmedir', 'Olumsal önermedir', 'Yalnız p yanlışken doğrudur'], 'Her değer atamasında doğrudur; ilginç olan, koşullu bağlacını kullanan klasik mantıkta olumsuzluk olmadan da kurulabilmesidir.'),
  ('Üç terim ve iki öncülden oluşan klasik kıyasta (dört önerme türü A, E, I, O ile dört şekil dikkate alınınca) toplam kaç farklı kip olası olarak yazılabilir?', '256', ['64', '16', '128'], 'Her biri dört seçenekli iki öncül ve bir sonuç 4×4×4 = 64 kip yapar; dört şekille çarpılınca 256 olur.'),
  ('\'Bütün kediler hayvandır. Hiçbir köpek kedi değildir. O hâlde hiçbir köpek hayvan değildir.\' kıyasında hangi hata vardır?', 'Büyük terim sonuçta dağıtılmış, öncülde dağıtılmamış', ['Küçük terim sonuçta dağıtıldığı hâlde öncülde dağıtılmamıştır', 'Orta terim hiçbir öncülde dağıtılmadığı için sonuç zorunlu değildir', 'Aynı sözcük iki öncülde farklı anlamda kullanılmıştır'], 'Sonuçta \'hayvan\' (büyük terim) dağıtılmıştır, ancak büyük öncülde yüklem konumunda olumlu bir önermede yer aldığından dağıtılmamıştır.'),
  ('Birden çok kıyasın bir zincir oluşturacak biçimde sıralanıp, her sonucun bir sonraki kıyasın öncülü yapıldığı akıl yürütmeye ne ad verilir?', 'Sorites (zincirleme kıyas)', ['Entimem', 'Analoji', 'İkilem (iki seçenekli sonuç çıkarma)'], 'Sorites, art arda bağlanan kıyaslarda ara sonuçların açıkça söylenmeden yalnız öncüllerin sıralandığı bileşik akıl yürütmedir.'),
  ('Aşağıdaki önermelerden hangisi ters çevirme (kontrapozisyon) ile eşdeğer biçimde geçerli olarak çevrilemez?', 'Bazı öğrenciler gönüllüdür (I)', ['Bütün öğrenciler gönüllüdür (A)', 'Bazı öğrenciler gönüllü değildir (O)', 'Dördü de bu yolla sorunsuz çevrilebilir'], 'Kontrapozisyon A ve O için geçerlidir; I önermesinde \'bazı gönüllü olmayanlar öğrenci olmayandır\' çıkarımı zorunlu değildir.'),
  ('Modern yorumda (varoluşsal içerim olmadan) karşıtlık karesindeki ilişkilerden hangisi korunur?', 'Çelişiklik (A–O ve E–I)', ['Karşıtlık (A–E)', 'Alt karşıtlık (I–O): ikisi birlikte yanlış olamaz kuralı', 'Altlama (A\'dan I\'ya)'], 'Boş kümeler söz konusu olabileceğinden A ile E birlikte doğru olabilir, I ile O birlikte yanlış olabilir; yalnız çelişiklik kalır.'),
  ('\'Bu sayı ya çift ya da asaldır. Sayı çifttir. O hâlde asal değildir.\' akıl yürütmesindeki sorun nedir?', 'Seçenekler birbirini dışlamaz', ['Öncüller birbiriyle çelişir ve çıkarım bu yüzden geçersizdir', 'Orta terim dağıtılmamıştır', 'Öncülü yadsıma hatası vardır'], 'Kapsayıcı \'veya\' ile verilen seçeneklerden birinin doğruluğundan ötekinin yanlışlığı çıkarılamaz; 2 hem çift hem asaldır.'),
  ('\'Bu işi kabul edersem param olur, reddedersem huzurum olur. Ya kabul edeceğim ya reddedeceğim. O hâlde ya param olacak ya huzurum.\' akıl yürütmesi hangi türdendir?', 'Yapıcı ikilem', ['Yıkıcı ikilem', 'Hipotetik kıyas', 'Ayrık kıyas'], 'İki koşulludan ve öncüllerin ayrık onayından ayrık sonuç çıkaran akıl yürütme yapıcı ikilemdir.'),
  ('\'p → q\' ve \'q → r\' öncüllerinin yanında \'p ∧ ¬r\' birlikte doğru olabilir mi?', 'Hayır, bu üçü birlikte doğru olamaz', ['Evet, çünkü p doğru ve r yanlış olabilir', 'Yalnızca q yanlışsa olabilir', 'Yalnızca r doğruysa olabilir'], 'p doğruysa q ve r doğru olmalıdır; r\'nin yanlış olması çelişki doğurur.'),
  ('\'Ali ya evde ya okuldadır. Ali evde değil.\' bilgisi ve \'Ali\'nin gerçekte kütüphanede olması\' birlikte ele alındığında hangisi doğrudur?', 'Ayrık öncül yanlış olduğu için kıyasın sonucu güvenilmezdir', ['Kıyas biçimce geçerli olduğundan kesin sağlamdır ve sonuç güvenilirdir', 'Ali okulda olmalıdır diye zorunlu çıkarılır', 'Ali\'nin kütüphanede olması bir mantık hatasıdır'], 'Kıyas biçimce geçerlidir ama \'ya evde ya okulda\' öncülü yanlış olduğundan sağlam değildir.'),
  ('Gezegen Uranüs\'ün yörüngesinde bilinen kütle çekimleriyle açıklanamayan sapma kaldığında bu \'artık\'ın bilinmeyen bir gezegenden kaynaklandığı sonucuna varılması hangi yönteme örnektir?', 'Artık (kalıntı) yöntemi', ['Uyuşum yöntemi', 'Ayrılık yöntemi', 'Birlikte değişim yöntemi'], 'Bilinen nedenlerin açıkladığı kısım çıkarılınca kalan etki, geriye kalan nedene bağlanır; Neptün\'ün bulunmasına böyle gidilmiştir.'),
  ('Bir doktorun hastadaki ateş, öksürük ve halsizlik belirtilerini en iyi grip açıklar diyerek tanı koyması hangi çıkarım türüne örnektir?', 'Abdüksiyon', ['Tam tümevarım: bütün örnekler tek tek sayılmıştır', 'Kesin tümdengelim: sonuç zorunlu olarak çıkmıştır', 'Matematiksel tümevarım: n+1 adımına geçilmiştir'], 'Gözlenen belirtilerden geriye, onları açıklayan olası nedene gidilir; bu en iyi açıklamaya çıkarımdır.'),
  ('\'Her karga siyahtır\' önermesiyle mantıksal olarak eşdeğer olan hangisidir?', 'Siyah olmayan hiçbir şey karga değildir', ['Her siyah şey bir kargadır, çünkü ters yönde de geçerlidir', 'Bazı siyah şeylerin karga olduğu söylenebilir ama bütün için çıkmaz', 'Bazı kargaların siyah olmadığı, çünkü karşıt önerme budur'], 'A önermesi ile kontrapozisyonu eşdeğerdir; bu da Hempel\'in karga paradoksunun dayanağıdır.'),
  ('Hempel\'in karga paradoksuna göre mantıksal olarak \'Siyah olmayan her şey karga değildir\' önermesini doğrulayan bir gözlem hangisidir?', 'Beyaz bir ayakkabının karga olmaması', ['Kırmızı bir elmanın siyah olduğunun gözlenmesi', 'Bir kuzgunun kanatlarını açtığının gözlenmesi', 'Bir kargayı hiç görmemiş olmak'], 'Eşdeğerlik gereği siyah olmayan bir nesnenin karga olmadığının gözlenmesi de \'Her karga siyahtır\' önermesini destekler; bu sezgiye aykırı görünür.'),
  ('\'Hiçbir gerçek Türk bu müziği sevmez.\' \'Ama Ahmet Türk ve bu müziği seviyor.\' \'O zaman Ahmet gerçek bir Türk değildir.\' Bu yanıt hangi safsatadır?', 'Hiçbir gerçek İskoç safsatası', ['Yanlış ikilem', 'Acındırmaya başvurma', 'Bölme safsatası'], 'Genellemeyi çürüten örneği \'gerçek\' sözcüğünün anlamını değiştirerek dışarıda bırakmak bu safsatanın ölçütüdür.'),
  ('Bir kişi önce veriyi inceleyip rastgele bir kümeleşme buluyor, sonra \'asıl hipotezim buydu\' diyerek bu kümeyi açıklama olarak sunuyor. Bu hataya ne ad verilir?', 'Teksas keskin nişancı safsatası', ['Kumarbaz yanılgısı', 'Kırmızı ringa', 'Yeniliğe başvurma'], 'Hedefi vuruştan sonra çizmek gibi: örüntü bulunduktan sonra hipotez uydurulur; sınanabilir bir öngörü yoktur.'),
  ('\'Ölümden sonra hayat olmasaydı yaşamın anlamı kalmazdı; bu çok korkunç; o hâlde ölümden sonra hayat vardır.\' sözündeki hata nedir?', 'Sonuçların hoşa gitmemesine dayanma', ['Dört terim hatası, yani sözcüğün iki anlamda kullanılması', 'Çelişik önerme kullanmak, yani önermeyi kendisiyle çelişkiye sokmak', 'Zıt terimleri karıştırmak'], 'Bir önermenin hoş ya da hoş olmayan sonuçları doğruluğunu belirlemez; bu safsataya sonuçlara başvurma denir.'),
  ('Bir tartışmacı \'Bu kanıt yetmez\' dedikten sonra, kendisine ek kanıt sunulduğunda da kabul ölçütünü sürekli yükseltiyor. Bu hataya ne ad verilir?', 'Hedef tahtasını kaydırma', ['Hasır altı etme', 'Geleneğe başvurma', 'Birleştirme'], 'Karşı taraf koşulu sağladığında ölçütü değiştirerek tartışmayı sonsuza uzatmak bu safsatanın biçimidir.'),
  ('Lidya kralına verilen \'Halys\'ı geçersen büyük bir imparatorluğu yıkacaksın\' kehaneti kralın kendi imparatorluğunun yıkılmasıyla sonuçlandı. Bu söz hangi dilsel belirsizliği örnekler?', 'Yapı belirsizliği', ['Vurgu kaydırma', 'Birleştirme', 'Çoğunluğa başvurma'], 'Cümlenin hangi imparatorluğu kastettiği belirsiz olduğundan iki farklı yorum mümkündür; bu yapısal çift anlamlılıktır.'),
  ('\'Arkadaşlarına karşı DÜRÜST olmalısın\' cümlesinde vurguyu \'arkadaşlarına\' sözcüğüne kaydırıp \'başkalarına yalan söylenebilir\' sonucunu çıkarmak hangi safsatadır?', 'Vurgu (aksan) safsatası', ['Karmaşık soru', 'Kaygan zemin', 'Yanlış ikilem'], 'Cümlenin sözcüklerinden birinin vurgulanmasıyla asıl anlamdan farklı bir anlam çıkarılması vurgu safsatasıdır.'),
  ('\'Bir argüman safsata içeriyorsa sonucu da yanlıştır\' diyen kişi hangi hatayı yapar?', 'Safsata safsatası', ['Kaygan zemin', 'Bölme', 'Yeniliğe başvurma'], 'Bir argümanın kötü olması sonucunun yanlış olduğunu göstermez; sonuç başka gerekçelerle doğru olabilir.'),
  ('Hukuk öğrencisi Euathlus\'un hocası Protagoras\'a ders ücretini ilk davayı kazandığında ödeyeceği sözünü verip hiç dava almaması ve Protagoras\'ın dava açması hangi paradoksu doğurur?', 'Protagoras–Euathlus paradoksu', ['Berber paradoksu, yani kendini tıraş etmeyenler sorunu', 'Sorites paradoksu, yani yığın sorunu', 'Kunduracı paradoksu, yani ücret ödeme sorunu'], 'Mahkeme Euathlus\'un lehine karar verirse sözleşme gereği ödemez, aleyhine karar verirse mahkeme kararı gereği öder; iki taraf da kendi lehine ikilem kurabilir.'),
  ('Bir öğretmenin \'Gelecek hafta bir gün sürpriz sınav yapacağım; hangi gün olduğunu önceden bilemeyeceksiniz\' sözünün tutarlı olup olmadığı tartışması hangi paradoksun konusudur?', 'Sürpriz sınav paradoksu', ['Yalancı paradoksu, yani kendine gönderme sorunu', 'Yığın paradoksu, yani belirsiz sınır sorunu', 'Ok paradoksu, yani hareketsizlik sorunu'], 'Geriye doğru akıl yürütmeyle her günün elendiği sanılır; yine de sınav sürpriz biçimde yapılabilir. Bilgi ve öngörü kavramlarını sınar.'),
  ('Yalnızca kendisini tanımlamayan sıfatlara \'heterolojik\' denmesiyle ortaya çıkan \'heterolojik sözcüğü heterolojik midir?\' sorusu hangi mantıkçıların adıyla anılan paradokstur?', 'Grelling–Nelson', ['Peirce–Frege paradoksu', 'Zeno–Eubulides paradoksu', 'Boole–Venn paradoksu'], '1908\'de Kurt Grelling ve Leonard Nelson\'ın ileri sürdüğü bu paradoks, Russell paradoksunun dilsel bir benzeridir.'),
  ('Ortaçağ\'da Ramon Llull\'un \'Ars Magna\' adlı çalışmasında dönen halkalarla kavram birleştirmeleri üretmeyi denemesi mantık tarihinde neyin öncüsü sayılır?', 'Mantığın makineleştirilmesi fikrinin', ['Doğruluk tablolarının yöntemsel temelinin', 'Niceleyicilerin ilk simgesel kullanımının', 'Üç değerli mantığın ilk kullanımının'], 'Kavramları döner çarklarla birleştirerek sonuç üretme fikri, düşünmenin hesaba ve makineye indirgenmesi girişimlerinin erken bir örneğidir.'),
  ('Üçüncü hâlin olmaması ilkesiyle çelişmezlik ilkesi arasındaki fark nedir?', 'Birincisi çelişik iki önermenin birlikte yanlış olamayacağını, ikincisi birlikte doğru olamayacağını söyler', ['Birincisi birlikte doğru olamayacağını, ikincisi birlikte yanlış olamayacağını söyler', 'İkisi aynı ilkedir', 'Birincisi yalnız tümel önermeler için geçerlidir'], 'Çelişik önermelerden biri mutlaka doğrudur (üçüncü hâl yok) ve ikisi birlikte doğru olamaz (çelişmezlik).'),
  ('\'Bütün öğrenciler başarılıdır\' önermesi neden \'∀x (Ö(x) ∧ B(x))\' biçiminde yazılmaz?', 'Evrendeki her şeyin öğrenci olmasını gerektirir', ['Çünkü ∀ niceleyicisi koşullu bağlaçla hiçbir biçimde kullanılamaz', 'Çünkü başarılı terimi tikeldir', 'Çünkü öğrenci terimi soyuttur'], 'Doğru yazım ∀x (Ö(x) → B(x))\'dir; ve bağlacıyla yazmak öğrenci olmayanlar için de bu iki niteliği gerektirir.'),
  ('\'Yalnızca öğrenciler çalışkandır\' önermesi (Ö, Ç) hangi gösterime karşılık gelir?', '∀x (Ç(x) → Ö(x))', ['∀x (Ö(x) → Ç(x))', '∃x (Ö(x) ∧ Ç(x))', '∀x (Ö(x) ∧ Ç(x))'], '\'Yalnızca Ö, Ç\' demek çalışkan olan herkesin öğrenci olduğunu söyler; yön çalışkandan öğrenciye doğrudur.'),
  ('\'∀x (P(x) ∨ Q(x))\' ile \'∀x P(x) ∨ ∀x Q(x)\' önermeleri için hangisi doğrudur?', 'Mantıksal olarak eşdeğer değildir', ['Her zaman eşdeğerdir', 'İkincisi birinciyi gerektirmez ama birincisi ikinciyi gerektirir', 'İkisi de her zaman yanlıştır'], 'Evren tam sayılar, P çift, Q tek olsun: her sayı çift ya da tektir, ama ne hepsi çifttir ne hepsi tek.'),
  ('Bir çoban kurdu, keçiyi ve lahanayı nehrin karşı yakasına küçük bir kayıkla geçirmek zorundadır. Kayıkta çoban ile yalnız bir yük taşınabilir; çoban yokken kurt keçiyi, keçi lahanayı yer. Çoban en az kaç kez nehri geçer?', '7 geçiş', ['5 geçiş', '6 geçiş', '9 geçiş yapması gerekir'], 'Önce keçi geçer, çoban dönüp kurdu götürür ve keçiyi geri getirir, sonra lahanayı geçirir, dönüp keçiyi götürür: toplam 7 geçiş.'),
  ('1, 2, 5 ve 10 dakikada geçebilen dört kişi gece tek el fenerli bir köprüden geçmek zorundadır. Köprüden en çok iki kişi birlikte (yavaş olanın hızında) geçebilir. Hepsinin karşıya geçmesi en az kaç dakika sürer?', '17 dakika', ['19 dakika', '16 dakika', '20 dakika sürer'], '1 ve 2 geçer (2), 1 döner (1), 5 ile 10 geçer (10), 2 döner (2), 1 ve 2 geçer (2): toplam 17 dakika.'),
  ('Dışarıdan ayırt edilemeyen 27 bilyeden biri daha ağırdır. Kefeli bir teraziyle ağır bilyeyi kesin bulmak için en az kaç tartım yeter?', '3 tartım', ['2 tartım', '4 tartım', '5 tartım gerekir'], 'Her tartım adayları üçe böler; 27 = 3³ olduğundan üç tartım yeterlidir.'),
  ('Üç kutuda sırasıyla yalnız elma, yalnız portakal ve karışık meyve var; ancak kutular üzerindeki üç etiketin hepsi yanlış yapıştırılmıştır. En az bir meyve çıkarmak için hangi kutuya bakmak, etiketlerin hepsini düzeltmeye yeter?', '\'Karışık\' etiketli kutuya', ['\'Elma\' etiketli kutuya', '\'Portakal\' etiketli kutuya', 'Hangisine bakıldığı fark etmez'], '\'Karışık\' etiketi yanlış olduğundan kutu saf bir meyve içerir; çıkan meyve diğer iki etiketin yerini belirler.'),
  ('Bir adamın gideceği yolun iki ayrımı vardır: biri güvenli yola, öbürü uçuruma çıkar. Önünde biri hep doğru, biri hep yalan söyleyen iki bekçi bulunmaktadır ve hangisinin hangisi olduğunu bilmemektedir. Tek soruyla güvenli yolu bulmak için en uygun soru hangisidir?', 'Öteki bekçinin yanıtını sorup tersini seçmek', ['Hangi yol güvenlidir diye sorup söylenene gitmek, çünkü bekçi bilir', 'Sen şövalye misin diye sorup yanıta göre karar vermek', 'İki bekçiye ayrı ayrı sorup çoğunluğa uymak'], 'Doğru söyleyen yalancının yanıtını, yalancı doğruyu tersine aktarır; iki durumda da yanlış yolu işaret ettiğinden tersi seçilir.'),
  ('Bir listede şu dört cümle yazılıdır: 1) Bu listede tam bir yanlış cümle var. 2) Bu listede tam iki yanlış cümle var. 3) Bu listede tam üç yanlış cümle var. 4) Bu listede tam dört yanlış cümle var. Hangi cümle doğrudur?', 'Yalnız üçüncü cümle', ['Yalnız birinci cümle', 'Yalnız ikinci cümle', 'Dördüncü cümle'], 'Yalnız bir cümle doğruysa yanlış cümle sayısı üç olur; bu, yalnızca üçüncü cümlenin doğru olmasıyla tutarlıdır.'),
  ('Geçersiz bir kıyası, aynı biçimde ama açıkça yanlış sonuçlu paralel bir kıyas kurarak çürütme yöntemine ne ad verilir?', 'Paralel argümanla çürütme', ['Tam tümevarımla çürütme yöntemi', 'Çelişik alarak çürütme yöntemi', 'Dolaysız çıkarımla çürütme yöntemi'], 'Aynı biçimin öncülleri doğru, sonucu yanlış bir örneğini vermek, biçimin geçersiz olduğunu gösterir.'),
  ('Bir teorinin çürütülmesini önlemek için yalnız o çürütmeyi karşılamak üzere eklenen, bağımsız olarak sınanamayan varsayıma ne ad verilir?', 'Ad hoc hipotez', ['Aksiyom, yani kanıtlanmadan kabul edilen temel önerme', 'Totoloji, yani her durumda doğru olan önerme', 'Önkabul, yani tartışmanın başında verilen varsayım'], 'Ad hoc hipotez teoriyi kurtarır ama başka bir öngörü yapmadığı için bilimsel gücünü azaltır.'),
  ('\'Hava çok sıcak\' cümlesindeki \'çok sıcak\' ifadesi ile \'Ali Ahmet\'i Ayşe\'den çok sever\' cümlesi mantıksal olarak hangi sorunlara örnektir?', 'Birincisi bulanıklık, ikincisi yapı belirsizliği', ['İkisi de çelişki', 'Birincisi çok anlamlılık, ikincisi bulanıklık', 'İkisi de totoloji'], '\'Çok sıcak\' sınırı belirsiz bir ölçüt taşır; ikinci cümle ise iki ayrı okunuşa (Ali Ayşe\'yi mi Ahmet\'i mi daha çok sever) açıktır.'),
  ('Türkçedeki \'Gördüğüm adamın kardeşi\' gibi bir ifadenin birden fazla anlama gelebilmesi hangi sorunun örneğidir?', 'Yapıdan doğan belirsizlik', ['Bulanıklık, yani sınırı belli olmayan sözcük', 'Döngüsel tanım, yani tanımlananı içeren tanım', 'Totoloji, yani her durumda doğru cümle'], 'İfadede \'gördüğüm\' sözcüğü adamı mı kardeşi mi nitelediği belirsizdir; bu yapı kaynaklı çok anlamlılıktır.'),
  ('\'Linda zeki, açık sözlü, felsefe okumuş ve toplumsal adalete duyarlıdır.\' Buna göre \'Linda bankacıdır\' ile \'Linda hem bankacıdır hem feminist hareketin üyesidir\' ifadelerinin olasılıkları arasında nasıl bir ilişki olmak zorundadır?', 'İkincisi birincisinden büyük olamaz', ['İkincisi birincisinden büyüktür', 'İkisi birbirine eşit olmak zorundadır', 'Karşılaştırılamaz'], 'Bir olay ile onun öteki bir olayla birlikte gerçekleşmesi karşılaştırıldığında birleşik olayın olasılığı hiçbir zaman tek olayınkini aşamaz.'),
  ('Bir hastalık nüfusun yüzde 1\'inde görülüyor; testin hem duyarlılığı hem özgüllüğü yüzde 99\'dur. Testi pozitif çıkan rastgele bir kişinin gerçekten hasta olma olasılığı yaklaşık kaçtır?', 'Yüzde 50', ['Yüzde 99, yani testin doğruluğu kadar', 'Yüzde 1, yani hastalığın yaygınlığı kadar', 'Yüzde 90, yani duyarlılığın biraz altında'], '10.000 kişide 100 hasta (99 pozitif) ve 9.900 sağlam (99 yanlış pozitif) vardır; pozitiflerin yarısı hastadır.'),
  ('Bir hastalık binde bir görülüyor; test hasta olanların hepsini yakalıyor ama sağlamların yüzde 5\'inde yanlışlıkla pozitif çıkıyor. Testi pozitif çıkan birinin hasta olma olasılığı yaklaşık kaçtır?', 'Yüzde 2', ['Yüzde 95', 'Yüzde 50', 'Yüzde 20'], '100.000 kişide 100 hasta ve yaklaşık 4.995 yanlış pozitif vardır; 100 / (100 + 4.995) ≈ %2.'),
  ('İlk sınavda çok yüksek puan alan öğrencilerin ikinci sınavda ortalama olarak biraz daha düşük puan almasını \'ödül verilmediği için çabayı bıraktılar\' diye açıklamak hangi hatadır?', 'Ortalamaya dönüşü gözden kaçırma', ['Gerçek neden olmayan çabayı ödüle bağlama hatası ve genelleme', 'Çoğunluğa başvurma', 'Kaygan zemin'], 'Uç değerler çoğu zaman bir sonraki ölçümde ortalamaya yaklaşır; bu istatistiksel olgu için gereksiz nedensel açıklama kurulur.'),
  ('İllerin ortalama gelir düzeyi ile hastalık oranı arasında bir ilişki bulunduğuna bakıp bundan \'zengin bireyler daha az hastalanır\' sonucunu çıkarmak hangi hataya yol açabilir?', 'Ekolojik yanılgı', ['Aceleci genelleme', 'Kaygan zemin', 'Bölme safsatası'], 'Topluluk düzeyindeki bir ilişkiyi bireylere taşımak ekolojik yanılgıdır; ilişki bireyler düzeyinde farklı olabilir.'),
  ('Bir hastanede iki tedavinin başarı oranı hem hafif hem ağır hasta grubunda birinci tedavi lehine iken toplam başarı oranının ikinci tedavi lehine çıkabilmesine ne ad verilir?', 'Simpson paradoksu', ['Zenon paradoksu', 'Berber paradoksu', 'Newcomb paradoksu'], 'Alt gruplardaki eğilimin toplam veride tersine dönmesi, grupların büyüklüklerinin dengesiz olmasından doğar.'),
  ('Bir mahkemede \'Masum birinin DNA\'sının bu kanıtla eşleşme olasılığı milyonda birdir; o hâlde sanığın masum olma olasılığı milyonda birdir\' denmesi hangi hatadır?', 'Savcı safsatası: koşullu olasılığın yönünü karıştırma', ['Kumarbaz yanılgısı', 'Konu saptırma', 'Yeniliğe başvurma'], 'P(kanıt | masum) ile P(masum | kanıt) aynı şey değildir; ikincisi için temel oran da gerekir.'),
  ('Bir araştırmacı yirmi farklı gıdayı ayrı ayrı test edip yalnız \'anlamlı\' çıkan birini yayımlıyor, öteki on dokuz denemeyi hiç anmıyor. Bu uygulama hangi sorunu doğurur?', 'Rastlantısal anlamlılığı gerçek sayma', ['Aksiyomlaştırma hatası, yani temel önermelerin eksik kurulması', 'Karşı örnek sorunu, yani tek bir örnekle çürütme', 'Modus ponens hatası, yani öncülü onaylayıp sonucu reddetme'], 'Yeterince çok test yapılırsa bazıları rastlantıyla anlamlı çıkar; bunu söylemeden yalnız o sonucu sunmak seçici raporlamadır.'),
  ('Bir ülkede nüfusun ortalama yaşı arttıkça kanser vakası sayısının da arttığı görülüyor. \'Kanser yaşlandırır\' sonucu hangi hatayı yansıtır?', 'Ters nedensellik ve yanlış neden', ['Birleştirme', 'Yanlış ikilem', 'Kırmızı ringa'], 'Kanser riski yaşla birlikte arttığı için ilişkinin yönü yaşlanmadan kansere doğrudur, tersine değildir.'),
  ('Aşağıdaki kıyaslardan hangisi geçerlidir?', 'Hiçbir bitki hareket etmez; bazı canlılar bitkidir; o hâlde bazı canlılar hareket etmez.', ['Bütün kediler hayvandır; bazı hayvanlar evcildir; o hâlde bazı kediler evcildir.', 'Bütün kuşlar yumurtlar; bütün sürüngenler yumurtlar; o hâlde bütün kuşlar sürüngendir.', 'Hiçbir kuş memeli değildir; hiçbir balık kuş değildir; o hâlde hiçbir balık memeli değildir.'], 'Yalnızca ikinci kıyas biçimce geçerlidir (Ferio); diğerlerinde orta terim dağıtılmamış ya da iki olumsuz öncül vardır.'),
  ('\'(p → q) ∧ (q → r)\' önermesi kaç satırda doğrudur?', '4 satırda', ['3 satırda, çünkü yalnız zincir doğru satırlar sayılır', '5 satırda, çünkü p yanlışken koşullular sağlanır', '6 satırda, çünkü iki koşullu bağımsızdır'], 'p-q-r değerleri (D,D,D), (Y,D,D), (Y,Y,D), (Y,Y,Y) olan dört satırda iki koşullu da doğrudur.'),
  ('Üç değişkenli \'p doğruysa q, p yanlışsa r\' mantığını kuran \'(p ∧ q) ∨ (¬p ∧ r)\' ifadesini sağlayan kaç farklı değer ataması bulunur?', 'Dört atama', ['Üç atama, çünkü iki bileşen çakışır', 'Beş atama, çünkü veya bağlacı toplar', 'Altı atama, çünkü yalnız iki satır yanlıştır'], 'p doğruyken q\'nun, p yanlışken r\'nin değeri sonucu belirler; böylece sekiz satırın yarısı doğrudur.'),
  ('p → q ve ¬p → q önermelerinin ikisi birden doğruysa q hakkında ne söylenebilir?', 'q doğrudur', ['q yanlıştır', 'q belirsizdir', 'q doğru da yanlış da olabilir'], 'p doğru ya da yanlış olsa da q doğru çıkar; bu durum analizine dayanan çıkarımdır.'),
  ('\'Aspirin ile ibuprofen birer ağrı kesicidir; kahve de uyandırıcıdır; yani hepsi aynı kategoridedir, hepsi ilaçtır\' sözü hangi hatayı yansıtır?', 'Yanlış denklik (yüzeysel benzerlikle eşitleme)', ['Kumarbaz yanılgısı (geçmişin geleceği etkilediğini sanma)', 'Tek nedene indirgeme (karmaşıklığı yok sayma)', 'Kuyuyu zehirleme (kaynağı itibarsızlaştırma)'], 'Birkaç ortak özelliğe bakıp temel farkları görmezden gelerek iki şeyi eşit göstermek yanlış denkliktir.'),
  ('Bir milletvekili şehir içi trafik sorununun sorulduğu tartışmada ulusal savunma harcamalarından uzun uzun söz ediyor. Bu uygulama neden mantıksal bir hatadır?', 'Soruya değil, başka bir konuya cevap vermiştir (konu dışılık)', ['Öncüllerini tutarsız kurmuştur (çelişki)', 'Terimleri tanımlamamıştır (belirsizlik)', 'Soruyu bütünüyle yanlış anlamıştır (dil hatası)'], 'Tartışılan konunun değil, başka bir konunun savunulması \'ignoratio elenchi\' (ilgisiz sonuç) hatasıdır.'),
  ('Bir tartışmacı kısa sürede onlarca zayıf iddia ve yarım alıntı sıralayarak karşı tarafın hepsine yanıt vermesini olanaksız kılıyor. Bu taktik nasıl adlandırılır?', 'Gish galopu', ['Kumarbaz yanılgısı', 'Döngüsel akıl yürütme', 'Yeniliğe başvurma'], 'Hızlı biçimde çok sayıda iddia sıralamak, her birini yanıtlamanın zorluğunu kendi lehine kullanmaktır.'),
  ('Megaralı Philon\'un \'koşullu önermesi yalnız öncül doğru, sonuç yanlışken yanlıştır\' görüşü modern mantığın hangi kavramının öncüsüdür?', 'Maddi koşullu', ['Çift koşullu', 'Dışlayıcı veya', 'Niceleyici'], 'Antik tartışmada Philon\'un önerdiği tanım, modern doğruluk tablosundaki koşullu bağlaçla örtüşür.'),
  ('Leibniz\'in, bütün akıl yürütmelerin cebirsel hesaba indirgenebileceğini hayal eden \'calculus ratiocinator\' (akıl yürütme hesabı) fikri mantık tarihinde neyle ilişkilendirilir?', 'Mantığın hesaba indirgenmesi', ['Safsataların sınıflandırılmasıyla', 'Venn diyagramlarıyla', 'Doğruluk tablosunun bulunmasıyla'], 'Leibniz\'in evrensel simgesel dil ve hesap ideali, Boole ve Frege gibi sonraki mantıkçılara esin kaynağı oldu.'),
  ('Kıyasın biçimsel yapısını dört şekle ve belirli kiplere ayıran Aristotelesçi öğretiyi Orta Çağ\'da hatırlatma sözcükleriyle (Barbara, Celarent...) sistemleştiren dönem hangisidir?', 'Skolastik dönem', ['Antik Roma imparatorluğu dönemi', 'Rönesans\'ın sonu', '20. yüzyıl'], 'Barbara, Celarent gibi hatırlatma sözcükleri 13. yüzyıl skolastik mantık kitaplarında yaygınlaştı.'),
  ('Aristoteles mantığının yüzyıllar boyunca hâkim olmasını Kant \'mantığın o zamandan beri bir adım ileri ya da geri gitmediği\' sözüyle anlatmıştır. Bu görüşü çürüten 19. yüzyıl gelişmesi hangisidir?', 'Simgesel mantık', ['Skolastik kıyas sistemlerinin yazılması', 'Safsatalar listesinin genişletilmesi', 'Retorik kitaplarının çoğalması'], 'Simgesel mantık, ilişkiler ve niceleyicileri içerek klasik kıyas kuramının sınırlarını aşmıştır.'),
  ('Gündelik akıl yürütmede \'Anahtar kapının önünde değil, ışığın olduğu yerde aranır\' benzetmesi hangi hatayı anlatır?', 'Kanıtı, bulunması kolay olan yerde arama', ['Aşırı genelleme', 'Döngüsel akıl yürütme', 'Kıyasta orta terimin dağıtılmaması'], 'Aranan şeyin gerçekte bulunabileceği yer yerine aramanın kolay olduğu yerde arayıp sonucu buna bağlamak, ölçme yanlılığına örnektir.'),
  ('Bir adada üç sakinle karşılaşırsınız; şövalyeler hep doğru, yalancılar hep yanlış söyler. Mert: "aramızda en az bir şövalye vardır." Lale: "Mert ya da Kerem şövalyedir." Kerem: "Mert şövalyeyse Lale yalancıdır." Bu söylemlere göre aşağıdakilerden hangisi doğrudur?', 'Mert ile Lale şövalyedir, öteki yalancıdır', ['Mert ile Kerem şövalyedir, öteki yalancıdır', 'Yalnız Lale şövalyedir', 'Yalnız Mert şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'mert ile lale şövalyedir, öteki yalancıdır\' durumu üç söz için de tutarlıdır.'),
  ('Bir bilmecede üç kişi konuşuyor ve her biri ya daima doğru ya daima yanlış söylüyor: Aslı → "Cenk şövalyeyse Ferhat yalancıdır"; Cenk → "aramızda tam iki yalancı vardır"; Ferhat → "aramızda en az bir şövalye vardır". Çözüm aşağıdakilerden hangisidir?', 'Aslı ile Ferhat şövalyedir', ['Cenk ile Ferhat şövalyedir, öteki yalancıdır', 'Üçü de şövalyedir', 'Yalnız Ferhat şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'aslı ile ferhat şövalyedir, öteki yalancıdır\' durumu üç söz için de tutarlıdır.'),
  ('Bir kabilede şövalyeler yalnız doğru, yalancılar yalnız yanlış konuşur. Üç kabile üyesinden Tarık \'üçümüz de yalancıyız\', Elif \'Tarık ve Deniz yalancıdır\', Deniz \'aramızda en az bir şövalye vardır\' demiştir. Hangi yargı bu bilgilerle kesin olarak doğrudur?', 'Yalnız Deniz şövalyedir', ['Tarık ile Deniz şövalyedir, öteki yalancıdır', 'Elif ile Deniz şövalyedir, öteki yalancıdır', 'Üçü de şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'yalnız deniz şövalyedir\' durumu üç söz için de tutarlıdır.'),
  ('Üç arkadaştan her biri ya hep gerçeği ya da hep yalanı söylemektedir. Defne "Barış ve Yağmur yalancıdır" diyor, Barış "aramızda tam bir yalancı vardır" diyor, Yağmur ise "Defne ile Barış farklı türdendir" diyor. Bu durumda türleri için ne söylenebilir?', 'Barış ile Yağmur şövalyedir', ['Üçü de şövalyedir', 'Yalnız Yağmur şövalyedir', 'Yalnız Barış şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'barış ile yağmur şövalyedir, öteki yalancıdır\' durumu üç söz için de tutarlıdır.'),
  ('p: \'Sınav kolay\', q: \'Süre yeterli\'. \'Sınav kolay ve süre yeterli olmadıkça başarı artmaz\' cümlesinde koşul yapısı hangisidir? (r: \'Başarı artar\')', 'r → (p ∧ q)', ['(p ∧ q) → r', '¬r → (p ∧ q)', 'r ↔ (p ∨ q)'], '\'Olmadıkça ... olmaz\' kalıbı gerek koşul bildirir: başarı arttıysa sınav kolay ve süre yeterli olmuştur.'),
  ('\'Hiçbir öğrenci sınıfta değildir ya da öğretmen sınıftadır\' cümlesi, p: \'Bir öğrenci sınıftadır\' ve q: \'Öğretmen sınıftadır\' ile nasıl yazılır?', '¬p ∨ q', ['¬(p ∨ q)', 'p → ¬q', '¬p ∧ q'], 'Cümlenin ilk yarısı \'bir öğrenci sınıfta değil\' ile eşdeğerdir; ikinci yarı q ile veya bağlanır.'),
  ('p: \'Ali hastadır\', q: \'Ali okula gelmez\'. \'Ali hasta değilse okula gelir\' cümlesinin q ile gösterimi hangisidir?', '¬p → ¬q', ['p → ¬q', '¬p → q', 'p ∧ ¬q'], 'q \'okula gelmez\' olduğundan \'okula gelir\' ¬q\'dur: ¬p → ¬q.'),
  ('\'Bazı ağaçlar yaprak dökmez\' önermesi doğru ise \'Hiçbir ağaç yaprak dökmez\' önermesi için ne söylenebilir?', 'Belirsizdir', ['Doğrudur', 'Yanlıştır', 'Çelişiktir'], 'O doğru ise E için ancak I doğru olursa yanlış denebilir; O doğru olunca E belirsizdir (tikeller birlikte doğru olabilir).'),
  ('Bütün mühendisler titizdir. Hiçbir titiz kişi hata kabul etmez. Bütün matematikçiler hata kabul eder. Bu öncüllerden hangisi kesinlikle çıkar?', 'Mühendis ile matematikçi ayrıktır', ['Bütün matematikçiler mühendistir', 'Bazı mühendisler matematikçidir', 'Bütün mühendisler matematikçidir'], 'Mühendisler titiz, titizler hata kabul etmez; matematikçiler hata kabul eder. Bu yüzden mühendis ile matematikçi ayrıktır.'),
  ('Bütün kitaplar sayfalıdır. Bazı dergiler kitap değildir. Hiçbir sayfalı şey su geçirmez. Bu öncüllerden hangisi kesin olarak çıkar?', 'Hiçbir kitap su geçirmez', ['Hiçbir dergi su geçirmez', 'Bazı dergiler su geçirmez', 'Bütün kitaplar su geçirir'], 'Kitaplar sayfalı, sayfalılar su geçirmez; dergilerle ilgili öncül yalnızca bazılarını kitap dışı bırakır, dergi hakkında sonuç çıkmaz.'),
  ('Bütün yazılımcılar mantıklıdır. Bazı mantıklı insanlar şakacıdır. Hiçbir şakacı dikkatsiz değildir. Bu öncüllerden hangisi kesinlikle çıkar?', 'Bazı mantıklılar dikkatsiz değil', ['Bütün yazılımcılar şakacıdır', 'Hiçbir yazılımcı dikkatsiz değildir', 'Bazı yazılımcılar şakacıdır'], 'Mantıklı bir şakacı en az bir kişi vardır ve şakacı olan dikkatsiz olamaz; dolayısıyla bazı mantıklılar dikkatsiz değildir.'),
  ('Okul bahçesindeki camı kırma olayından sonra dört öğrenci ifade veriyor. Aras: "Derya doğru söylüyor." Beril: "Derya doğru söylüyor." Cemil: "Beril yalan söylüyor." Derya: "Beril yapmadı." Öğrencilerden tam bir tanesi doğru söylediğine göre camı kim kırmıştır?', 'Beril (ikinci kişi)', ['Aras (birinci kişi)', 'Cemil (üçüncü kişi)', 'Derya (dördüncü kişi)'], 'Her olası sorumlu için sözlerin doğruluğu sayılınca yalnızca Beril sorumlu olduğunda doğru söyleyenlerin sayısı bir olur ve söyleyenlerin türleriyle çelişki doğmaz.'),
  ('Ofiste bir bilgisayar kullanılamaz hale geldi. Dört çalışan şöyle konuştu: Aras: "Beril yapmadı." Beril: "Cemil yaptı." Cemil: "Aras yapmadı." Derya: "Aras yapmadı." İçlerinden tam iki kişi doğru söylediğine göre bilgisayarı kim bozmuştur?', 'Beril (ikinci kişi)', ['Aras (birinci kişi)', 'Cemil (üçüncü kişi)', 'Derya (dördüncü kişi)'], 'Her olası sorumlu için sözlerin doğruluğu sayılınca yalnızca Beril sorumlu olduğunda doğru söyleyenlerin sayısı iki olur ve söyleyenlerin türleriyle çelişki doğmaz.'),
  ('Kütüphanede bir kitabın sayfaları yırtılmıştır. Dört okuyucu ifade verdi: Aras: "Beril doğru söylüyor." Beril: "Aras yapmadı." Cemil: "Beril yaptı." Derya: "Aras yaptı." Bunlardan yalnızca üç tanesi doğru söylediğine göre sayfaları kim yırtmıştır?', 'Beril (ikinci kişi)', ['Aras (birinci kişi)', 'Cemil (üçüncü kişi)', 'Derya (dördüncü kişi)'], 'Her olası sorumlu için sözlerin doğruluğu sayılınca yalnızca Beril sorumlu olduğunda doğru söyleyenlerin sayısı üç olur ve söyleyenlerin türleriyle çelişki doğmaz.'),
  ('Üçüncü yüzyıl düşünürü Porphyrios\'un \'İsagoge\' adlı yapıtı, Aristoteles mantığına giriş niteliğiyle hangi öğretiyi yaygınlaştırmıştır?', 'Beş tümel', ['Dört kıyas şekli', 'Önermeler mantığı', 'Mill yöntemleri'], 'İsagoge, terimlerin birbirine bağlanma biçimlerini beş tümel altında toplar; Orta Çağ mantığının temel girişi olmuştur.'),
  ('Bir tartışmacı \'Bütün kanıtlar bu ilacın etkili olduğunu gösteriyor ama bu hâlâ tesadüf olabilir\' diyerek her şeyi reddediyor. Bu tutum hangi hatadır?', 'Aşırı kuşkucu tutumla kanıtı yok sayma', ['Aceleci genelleme', 'Kaygan zemin', 'Sonucu onaylama'], 'Güçlü kanıta rağmen tesadüf iddiasında ısrar etmek, tümevarım sonucunu kabul etmeyi reddeden tutumdur.'),
  ('\'Piyasa bugün cezalandırdı, ekonomi kızgın\' gibi söylemlerde soyut kavramların kişi gibi davranıyormuş gibi ele alınması hangi akıl yürütme hatasına yol açabilir?', 'Somutlaştırma (soyut kavramı varlık sayma)', ['Çoğunluğa başvurma (herkes yapıyor diye doğru sayma)', 'Çifte olumsuzlama', 'Tam sayım'], 'Soyut bir sürece iradeli bir varlık gibi davranmak, gerçek nedenlerin gizlenmesine neden olabilir.'),
  ('Bir iddiaya karşı \'Dediğiniz yarı doğru; ama yarısını söylemek, tamamen doğruymuş gibi sunmaktır\' denmesi neyi eleştirir?', 'Kısmi gerçeği tam gerçekmiş gibi sunma', ['Sonucun çelişkili olması', 'Bölme safsatası', 'Tanımın döngüsel olması'], 'Doğru olan bir kısmı vurgulayıp tamamlayıcı bilgiyi gizlemek, yanıltıcı bir akıl yürütme türüdür.'),
  ('\'Bazı öğrenciler gönüllüdür; ...; o hâlde bazı sporcular gönüllüdür\' kıyasında boşluğa hangi öncül yazılırsa sonuç zorunlu çıkar? (0: sporcu, 1: öğrenci, 2: gönüllü)', 'Bütün öğrenciler sporcudur', ['Bütün sporcular öğrencidir', 'Bazı sporcular öğrencidir', 'Hiçbir sporcu öğrenci değildir'], 'Gönüllü öğrencilerin hepsi sporcu olacağından en az bir sporcu gönüllüdür; iki tikel öncül ya da yönü ters öncül yetmez.'),
  ('Bir kartın bir yüzünde \'Öbür yüzdeki cümle doğrudur\', öbür yüzünde \'Öbür yüzdeki cümle yanlıştır\' yazılıdır. Bu durum hangi paradoksu oluşturur?', 'Jourdain paradoksu', ['Berber paradoksu', 'Grelling paradoksu', 'Newcomb paradoksu'], 'Birinci cümle doğruysa ikinci de doğru olmalı, bu da birincinin yanlış olmasını gerektirir; döngüsel bir çelişki doğar.'),
  ('\'Bu cümle doğruysa gökyüzü yeşildir\' cümlesinin paradoksal sonuç doğurmasının nedeni nedir?', 'Kendine gönderme', ['Olumsuzluk içermesi ve bunun doğurduğu sonuç', 'Soru biçiminde kurulması ve yanıt vermesi', 'Bileşik önerme olması ve bağlaçlar'], 'Curry paradoksunda cümlenin kendine gönderme yapması, herhangi bir önermeyi kanıtlamaya olanak verir.'),
  ('Evrensel genellemede (\'P(a) doğru, o hâlde ∀x P(x)\') hangi hataya düşülebilir?', 'Keyfî olmayan bir a\'dan genelleme yapmak', ['P(a) doğruyken sonucu yanlış bulmak', 'Niceleyici yerine bağlaç koymak', 'Totolojiyi kanıt saymak'], 'a keyfî seçilmiş (hiçbir ek özelliği olmayan) değilse tek örnek tüm evrene genellenemez.'),
  ('\'Bütün öğrenciler bir öğretmeni sever\' cümlesinin niceleyicileri sıralamayla ilgili iki okunuşu hangi sonucu doğurur?', 'İki okunuş farklıdır', ['İki okunuş eşdeğerdir', 'Cümle her zaman yanlıştır', 'Cümle önerme değildir'], 'Herkesin sevdiği bir öğretmen varlığı ile her öğrencinin kendi öğretmenini sevmesi farklı önermelerdir; ilki ikincisini gerektirir, tersi değil.'),
  ('Beş öğrenci rafa dizilmiş beş kitabı sırayla okuyacak. Deniz birinci okur; Ali tam ortadaki sırayı alır; Ece, Bora\'dan önce okur; Bora, Ceren\'in hemen önünde okur. Ceren kaçıncı okur?', 'Beşinci', ['Dördüncü', 'Üçüncü', 'İkinci'], 'Deniz 1., Ali 3. olunca Ece 2., Bora 4. ve Ceren 5. olur; başka yerleşim koşullarla çelişir.'),
  ('2, 4, 8, 16 dizisinde bir kişi sonraki sayının 32 olacağını, başka biri ise farklı bir kuralla 31 olacağını öne sürüyor. Bu durum tümevarımın hangi özelliğini gösterir?', 'Sınırlı veriden birden çok kuralın çıkarılabilmesini, yani sonucun kesin olmadığını', ['Her dizinin tek bir kuralı olduğunu', 'Tümdengelimin her zaman yanlış olduğunu', 'Sayıların rastgele olduğunu'], 'Sonlu sayıda gözlem birden çok genellemeyle uyumlu olabilir; bu yüzden tümevarım sonucu olasılıklıdır.'),
  ('Bir araştırmacı kuramının tahminlerinden biri gerçekleşmeyince önce ölçüm aletinin bozuk olabileceğini, sonra gözlem koşullarının yanlış olduğunu öne sürüyor. Bu hamle hangi mantıksal gerçeği yansıtır?', 'Bir tahmin tek başına hipotezi değil, hipotezle birlikte yardımcı varsayımları yanlışlar', ['Hipotezler hiçbir zaman sınanamaz', 'Yanlışlama yöntemi geçersizdir', 'Her gözlem hipotezi kanıtlar'], 'Tahminin başarısızlığı, kuram ve yardımcı varsayımların birleşiminin yanlışlığını gösterir; hangisinin sorumlu olduğu ayrıca incelenmelidir.'),
  ('Bir yazar, \'Devlet bir gemi gibidir, gemide kaptan nasıl tek karar verir; devlette de tek kişi karar vermelidir\' diyor. Bu akıl yürütmenin başlıca mantıksal zayıflığı nedir?', 'İki durum arasındaki ilgili farkların (yurttaşların katılımı, çıkar çeşitliliği) göz ardı edilmesi', ['Öncüllerin olumsuz olması', 'Kıyasın üçüncü şekilde olması', 'Tanımın çok kısa olması'], 'Benzetme tek yönlü benzerlikleri öne çıkarıp sonucu etkileyen farkları yok sayarsa zayıf analoji olur.'),
  ('\'Bu hayvan memeli ya da kuştur. Bu hayvan yumurta bırakıyor.\' Bu bilgilerle kuş olduğu sonucuna varmak neden güvenli değildir?', 'Yumurta bırakan memeliler de bulunur', ['Kuşlar yumurta bırakmaz', 'Ayrık öncül geçerli değildir', 'Önermeler bağlaçsızdır'], 'Ördek gagalı ve kloakalılar gibi yumurtlayan memeliler bulunduğundan yumurta bırakmak tek başına kuşluğu göstermez.'),
  ('\'Eğer hava açıksa piknik yaparız\' önermesinin \'sadece hava açıksa piknik yaparız\' hâlinden farkı nedir?', 'İkincisi hava açıklığını piknik için gerek koşul yapar', ['İkisi aynı anlama gelir', 'İlki gerek koşul bildirir', 'İkincisi hiçbir koşul bildirmez'], '\'Sadece ... ise\' ifadesi öncülü zorunlu koşul yapar: piknik yapıldıysa hava açıktır.'),
  ('\'Üçgenin iki kenarı eşitse iki açısı eşittir\' önermesinin tersi (iki açı eşitse iki kenar eşittir) için ne söylenebilir?', 'Üçgenlerde bu da doğrudur, dolayısıyla koşul iki yönlüdür', ['Her zaman yanlıştır', 'Belirsizdir', 'Önerme değildir'], 'İkizkenar üçgende taban açıları eşitliğinin tersi de geçerlidir; bu iki yönlü ilişki gerek ve yeter koşuldur.'),
  ('\'Doğada güçlü olan hayatta kalır; öyleyse güçlü olanın hayatta kalması ahlaken doğrudur\' sözündeki akıl yürütme hangi hataya düşer?', 'Olandan olması gerekene geçme (doğalcı safsata)', ['Kumarbaz yanılgısı (geçmişin geleceği etkilediğini sanma)', 'Seçici kanıt kullanma', 'Kırmızı ringa (konuyu ilgisiz bir yöne çekme)'], 'Bir olgunun var olması, onun iyi ya da doğru olduğunu göstermez; betimleyici öncülden normatif sonuç çıkarılmıştır.'),
  ('Bir tartışmacı \'Her şey rastlantıdır; hiçbir şeyin sebebi olamaz\' dedikten sonra kendi iddiasının sebebini sorulduğunda yanıt veremiyor. Bu durum hangi mantık sorununu yansıtır?', 'Kendini çürüten (özneye dönen) iddia', ['Aceleci genelleme', 'Yeniliğe başvurma', 'Bölme safsatası'], 'İddia doğruysa kendisinin de sebebi olamaz; böylece kendi gerekçelendirilmesini zayıflatır.'),
  ('Bir kişi eski bir yanlış inancını savunurken \'Dedem de böyle inanırdı\' diyor ve aynı zamanda \'Bu düşünce çok yeni, rağbet görmedi\' diyerek başka bir görüşü reddediyor. Bu söylemin tutarsızlığı nedir?', 'Eski olmayı erdem, yeni olmayı kusur sayan iki karşıt safsatayı keyfi biçimde kullanması', ['Dört terim hatası', 'Kıyasta orta terimin dağıtılmaması', 'Çıkarımın totoloji olması'], 'Geleneğe başvurma ile yeniliği küçümseme aynı ölçütle uygulanmadığında çelişkili bir ikna tarzı doğar.'),
  ('Üç değerli bir sistemde değerler D (doğru), Y (yanlış) ve ara değer olan M\'dir (sıralama: Y < M < D). \'ve\' bağlacı iki bileşenin en küçüğünü aldığına göre \'M ∧ D\' bileşiğinin değeri nedir?', 'M', ['D', 'Y', 'Tanımsız'], 'Ve bağlacı en küçük değeri alır: min(M, D) = M.'),
  ('\'Bütün hekimler eğitimlidir. Bütün hekimler çalışkandır. O hâlde bütün çalışkanlar eğitimlidir.\' kıyasının geçersizliği hangi kuralın çiğnenmesinden doğar?', 'Sonuçta dağıtılan küçük terim öncülde dağıtılmamıştır', ['Orta terim dağıtılmamıştır', 'İki olumsuz öncül vardır', 'Dört terim kullanılmıştır'], '\'Çalışkan\' sonuçta konu olarak dağıtılmıştır, oysa küçük öncülde yüklem olduğundan dağıtılmamıştır; bu küçük terimin yetkisiz dağıtımıdır.'),
  ('\'Bütün ejderhalar ateş püskürtür. O hâlde bazı ejderhalar ateş püskürtür.\' çıkarımı modern mantıkta neden geçersiz sayılır?', 'Ejderhaların varlığı varsayılmadan tümelden tikele geçilemez', ['Orta terim dağıtılmamıştır', 'İki olumsuz öncül vardır', 'Dört terim kullanılmıştır'], 'Boole yorumunda tümel önerme boş kaplamlı terimle doğru olabilir; tikel sonuç ise bir varlık iddiasıdır.'),
  ('Öncülleri ve sonucu gerçekte doğru olan bir argüman için hangisi söylenebilir?', 'Geçerli de geçersiz de olabilir', ['Mutlaka geçerlidir', 'Mutlaka geçersizdir', 'Mutlaka sağlamdır'], 'Argümanın geçerliliği biçime bağlıdır; doğru öncül ve doğru sonuç tesadüfen bir arada olabilir.'),
  ('Yalnızca NAND (↑) kullanılarak \'p ∧ q\' nasıl yazılır?', '(p ↑ q) ↑ (p ↑ q)', ['(p ↑ p) ↑ (q ↑ q)', 'p ↑ (q ↑ q)', '(p ↑ q) ↑ p'], 'p ↑ q, p ∧ q\'nun olumsuzudur; onu kendisiyle NAND\'lamak olumsuzlayarak p ∧ q\'yu verir.'),
  ('Yalnızca NOR (↓) kullanılarak \'p ∨ q\' nasıl yazılır?', '(p ↓ q) ↓ (p ↓ q)', ['(p ↓ p) ↓ (q ↓ q)', 'p ↓ (q ↓ q)', '(p ↓ q) ↓ p'], 'p ↓ q, p ∨ q\'nun olumsuzudur; onu kendisiyle NOR\'lamak olumsuzlayarak p ∨ q\'yu verir.'),
];
